import os
from amazon_textract import TextractClient

def extract_receipt_fields(payload, config=None):
    config = config or {}
    client = TextractClient(
        region_name=config.get('region_name', 'us-east-1'),
        aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY')
    )

    response = client.detect_document_text(Document={'Bytes': payload})

    lines = []
    for item in response['Blocks']:
        if item['BlockType'] == 'LINE':
            lines.append(item['Text'])

    result = {
        'merchant': None,
        'tax': None,
        'total': None,
        'items': []
    }

    for line in lines:
        if 'Total' in line or 'TOTAL' in line:
            result['total'] = float(line.split()[-1].replace('$', ''))
        elif 'Tax' in line or 'TAX' in line:
            result['tax'] = float(line.split()[-1].replace('$', ''))
        elif len(line.split()) == 2 and '$' in line:
            try:
                amount = float(line.split()[-1].replace('$', ''))
                result['items'].append(line.split()[0])
            except:
                continue
        elif result['merchant'] is None and len(line) > 3:
            result['merchant'] = line

    return result
